// "now with dependency injection!"
 const container = new GlobalContainer();
 container.register('Mailer', new SmtpMailer(process.env.SMTP!));
 container.register('Repo', new PostgresOrderRepo(process.env.DB_URL!));

 class OrderService {
   constructor() {} // takes nothing

   async place(order: Order) {
     const repo = container.get('Repo');      // hidden dependency
     const mailer = container.get('Mailer');  // hidden dependency
     await repo.save(order);
     await mailer.send(order.email, 'placed');
   }
 }

